import{_ as p,a0 as l,w as s,s as n,I as r,x as e,a1 as T,A as a,ao as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"初识 HTTP/2（一） | LCTT x X-CMD","titleTemplate":false,"description":"初识 HTTP/2（一） | LCTT (201701) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"初识 HTTP/2（一） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"初识 HTTP/2（一） | LCTT (201701) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201701/20160823 Getting Started with HTTP2 - Part 1","title":"初识 HTTP/2（一）","tag":"201701","desc":""},"relativePath":"201701/20160823 Getting Started with HTTP2 - Part 1.md","filePath":"[post].md"}'),d={name:"201701/20160823 Getting Started with HTTP2 - Part 1.md"};function m(P,t,H,u,g,f){const i=l("Link");return s(),n("div",null,[t[22]||(t[22]=r("h1",{id:"初识-http-2-一",tabindex:"-1"},[e("初识 HTTP/2（一） "),r("a",{class:"header-anchor",href:"#初识-http-2-一","aria-label":"Permalink to “初识 HTTP/2（一）”"},"​")],-1)),t[23]||(t[23]=r("p",null,[r("img",{src:"https://static.viget.com/_284x284_crop_center-center/http2-pizza.png?mtime=20160822160641",alt:""})],-1)),t[24]||(t[24]=r("blockquote",null,[r("p",null,"用披萨来说明当你订单数很大的时候 HTTP/2 是怎么打败 HTTP/1.1 的。")],-1)),r("p",null,[t[1]||(t[1]=e("在建立网站和应用的方式上 HTTP/2 有些令人惊叹的改变，在 HTTP/2 发布后的一年半，几乎 ",-1)),T(i,{href:"https://w3techs.com/technologies/details/ce-http2/all/all"},{default:a(()=>[...t[0]||(t[0]=[e("10% 的网站使用了 HTTP/2",-1)])]),_:1}),t[2]||(t[2]=e("。它绝对值得采用，但是这篇文章应该首先推给使用 HTTP/2 的前端开发者。这个连载的文章是指导前端开发者怎么转换到 HTTP/2。",-1))]),t[25]||(t[25]=o('<p>本文涵盖了 HTTP/2 对 HTTP/1.1 来说有什么提高的内容，并且向前端开发者介绍了 HTTP/2。</p><h3 id="再次让我想起什么是-http" tabindex="-1">再次让我想起什么是 HTTP ... <a class="header-anchor" href="#再次让我想起什么是-http" aria-label="Permalink to “再次让我想起什么是 HTTP ...”">​</a></h3><p>超文本传输协议，也就是 HTTP，这个协议决定了 web 内容怎么传输。HTTP/1.1 在 1999 年被标准化，那时候的 web 和现在有很大的不同，表格霸占了整个网络。样式通常被内联在元素中，如果网站管理员更加的细致，他们会在头部写个 <code>&lt;style&gt;</code>标签。 JavaScript 也被丢在文档里面，那时候完整的网站通常也不会超过几页。</p><p>HTTP/1.1 预计这种情况会持续一段时间，所以它并没有太过关注在让一个站点可以加载大量的资源方面，因为那时候的开发者并不需要这个。因此它使用了一个非常简单的方式来处理资源，你访问一个资源然后服务器去寻找它，并且返回你访问的资源，或者告诉你这个资源不存在。这种被叫作&quot;线头堵塞&quot;方式非常高效，但是当你需要多个资源的时候，这个进程会依次寻找每个资源。这意味着在你访问第二个资源之前，服务器必须找到你访问的第一个资源并且载入它，或者告诉你没找到。</p><h3 id="大型站点的发展" tabindex="-1">大型站点的发展 <a class="header-anchor" href="#大型站点的发展" aria-label="Permalink to “大型站点的发展”">​</a></h3><p>在 1999 年之后的几年里，随着 php 和其他像 Rails 这样的动态语言的崛起，站点变得越来越复杂。css 文件也随着向响应式开发的转变而变的越来越大，因此像 Sass 这样的可以创造一个简单的工作环境的 CSS 编译器就应运而生。 JavaScript 也在 web 上有了更大的作用，它允许开发者编写复杂的应用，这曾经只是 C++ 开发人员的工作。随着 Retina 和高清显示屏的兴起，也让图片变得更高清。随着这些改变，文件大小呈现指数式的增长，使得本来是等待几个字节的资源变成了加载几千字节，甚至在某些情况下有几兆。当你开始载入页面的其它东西前，必须先载入数百 K 的东西，你只能乐观的假设你的用户有很快的网络接入。</p><p>想象 HTTP/1.1 是个过去的那种柜台购买式的街旁披萨店。你能自己过去并且预定一个雪碧和 2 片 Angry Hawaiian ，然后等待 3 分钟。他们可以很容易地处理这些，实际上这是一个蓬勃发展的商业模式-定单简单、处理迅速。</p><p><img src="https://static.viget.com/_300xAUTO_crop_center-center/http2-pizzaorder1.png?mtime=20160823122331" alt=""></p><p>然而，一旦你决定在同样的披萨店主办一场小区域的季度颁奖典礼，事情就变的更复杂了。每个人都预定不同的东西，快速而杂乱无章让等待时间直线上升。</p><p><img src="https://static.viget.com/_300xAUTO_crop_center-center/http2-pizzaorder2.png?mtime=20160823130750" alt=""></p><h3 id="哪里是-http-2-的舞台" tabindex="-1">哪里是 HTTP/2 的舞台 <a class="header-anchor" href="#哪里是-http-2-的舞台" aria-label="Permalink to “哪里是 HTTP/2 的舞台”">​</a></h3><p>HTTP/2 对前端开发者主要的承诺就是复用。意思就是资源请求能发生在同一时间，并且服务器能马上响应这些资源。在请求之间没有等待，因为它们发生在同一时间。</p><p>使用同样的比喻，HTTP/2 允许披萨店在餐馆他们自己区域举办派对。派一个服务员接受订单，并把所有已经准备好的订单交付。当其他人的比萨在制作的时候，你也不需要花 30 分钟去等待你的雪碧，它们在第一批交付的东西之中。这方式使得管理大量订单更加简单，并且防止人们等他们的订单时间太长。</p><p>复用带给我们的 web 开发的大变化是改变了文件的加载方式。帮助绕过资源加载的 HTTP/1.1 瓶颈的方式是通过连接和压缩需要被加载的文件。所有任务运行器都默认采取这样的操作方式，或者需要作一点小设置就行。和过去一样，开发人员可以将图像放在精灵拼图（sprite sheets）中，这会减少了对服务器的请求数。</p><h3 id="改进-http-1-1" tabindex="-1">改进 HTTP/1.1 <a class="header-anchor" href="#改进-http-1-1" aria-label="Permalink to “改进 HTTP/1.1”">​</a></h3>',15)),r("p",null,[t[4]||(t[4]=e("将文件连接起来是个处理 HTTP1.1 的请求限制问题的非常聪明的方式，但是连接文件的主要问题是它要求用户第一次访问整个网站时下载所有的资源。一旦它们载入后，浏览器就会缓存所有的资源。这能提高用户每次访问网页时的速度，但是前期负载很重，对",-1)),T(i,{href:"https://blog.kissmetrics.com/speed-is-a-killer/"},{default:a(()=>[...t[3]||(t[3]=[e("跳出率不利",-1)])]),_:1}),t[5]||(t[5]=e("。此外，他们可能为所不访问的页面加载资源。期望用户访问每个页面以查看每个样式，并与每个脚本进行交互是不现实的。此外，在加拿大和欧洲以及几乎每个美国移动提供商的地方，有每月的带宽上限。不是加载额外的 54 千字节的内容就会超过每月的流量限制，而是让我们假设用户想保留这些额外的流量看 Taylor Swift 的 gif。",-1))]),t[26]||(t[26]=r("p",null,"使用 HTTP/2 和多路复用，您可以开发一些最高效的网站，但它需要一些重新思考、甚至​​撤销之前的最佳做法。重复一次，我的目的是加快 HTTP/2 的会话，使用我们新的工具，我们可以发现这些新的最佳的做法。",-1)),r("p",null,[t[7]||(t[7]=e("在我的下一篇文章，",-1)),T(i,{href:"https://www.viget.com/articles/getting-started-with-http-2-part-2"},{default:a(()=>[...t[6]||(t[6]=[e("我将探索建设基于 HTTP/2 的网站的一些最好方式",-1)])]),_:1}),t[8]||(t[8]=e("。",-1))]),t[27]||(t[27]=r("hr",null,null,-1)),r("p",null,[t[10]||(t[10]=e("via: ",-1)),T(i,{href:"https://www.viget.com/articles/getting-started-with-http-2-part-1?imm_mid=0eb24a&cmp=em-web-na-na-newsltr_20161130"},{default:a(()=>[...t[9]||(t[9]=[e("https://www.viget.com/articles/getting-started-with-http-2-part-1?imm_mid=0eb24a&cmp=em-web-na-na-newsltr_20161130",-1)])]),_:1})]),r("p",null,[t[14]||(t[14]=e("作者：",-1)),T(i,{href:"https://www.viget.com/about/team/btinsley"},{default:a(()=>[...t[11]||(t[11]=[e("Ben",-1)])]),_:1}),t[15]||(t[15]=e(" 译者：",-1)),T(i,{href:"https://github.com/hkurj"},{default:a(()=>[...t[12]||(t[12]=[e("hkurj",-1)])]),_:1}),t[16]||(t[16]=e(" 校对：",-1)),T(i,{href:"https://github.com/wxy"},{default:a(()=>[...t[13]||(t[13]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[19]||(t[19]=e("本文由 ",-1)),T(i,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[17]||(t[17]=[e("LCTT",-1)])]),_:1}),t[20]||(t[20]=e(" 组织编译，",-1)),T(i,{href:"https://linux.cn/"},{default:a(()=>[...t[18]||(t[18]=[e("Linux中国",-1)])]),_:1}),t[21]||(t[21]=e(" 荣誉推出",-1))])])}const x=p(d,[["render",m]]);export{b as __pageData,x as default};
